 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each nonzero cell is expanded to a tile that is the complement of
    # the input's occupancy pattern, in that cell's color.
    stamp = [[0 if grid[r][c] else 1 for c in range(w)] for r in range(h)]
    out = [[0] * (w * w) for _ in range(h * h)]
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value:
                for dr in range(h):
                    for dc in range(w):
                        if stamp[dr][dc]:
                            out[r*h+dr][c*w+dc] = value
    return out
